					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="tutupSub"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="showStatus || showJenis"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2 class="text-center text-base font-semibold text-ui-ink-gray-900">
								{{ showStatus ? 'Pilih Status' : 'Pilih Jenis Cuti' }}
							</h2>
							<p class="mb-4 mt-1 text-center text-xs text-ui-ink-gray-400">
								Bisa pilih lebih dari satu
							</p>

							<div class="max-h-[55vh] space-y-2 overflow-y-auto px-0.5">
								<button
									v-for="o in pilihanSub"
									:key="o"
									type="button"
									class="flex w-full cursor-pointer items-center justify-between gap-2 rounded-2xl border px-4 py-3.5 text-left transition"
									:class="
										arraySub.includes(o)
											? 'border-primary bg-primary/5'
											: 'border-ui-line-gray-200'
									"
									@click="pilihGanda(arraySub, o)"
								>
									<span class="flex min-w-0 items-center gap-2.5">
										<span
											v-if="showStatus"
											class="h-2.5 w-2.5 shrink-0 rounded-full"
											:class="titikStatus(o)"
										/>
										<span
											class="truncate text-xs font-medium text-ui-ink-gray-800"
											>{{ o }}</span
										>
									</span>
									<span
										class="flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 transition"
										:class="
											arraySub.includes(o)
												? 'border-primary bg-primary text-ui-onPrimary'
												: 'border-ui-line-gray-300'
										"
									>
										<svg
											v-if="arraySub.includes(o)"
											xmlns="http://www.w3.org/2000/svg"
											viewBox="0 0 24 24"
											class="h-3.5 w-3.5"
											fill="none"
											stroke="currentColor"
											stroke-width="3"
											stroke-linecap="round"
											stroke-linejoin="round"
										>
											<path d="M20 6 9 17l-5-5" />
										</svg>
									</span>
								</button>
							</div>

							<div class="mt-5 flex items-center gap-3">
								<button
									type="button"
									class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
									@click="arraySub.splice(0)"
								>
									Reset
								</button>
								<button
									type="button"
									class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
									@click="tutupSub"
								>
									Selesai
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ====== Sub-sheet RENTANG TANGGAL ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="showTanggal"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="showTanggal = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="showTanggal"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2 class="text-center text-base font-semibold text-ui-ink-gray-900">
								Tanggal Cuti
							</h2>
							<p class="mb-4 mt-1 text-center text-xs text-ui-ink-gray-400">
								Cuti yang mulai dan selesai dalam rentang ini
							</p>

							<div class="space-y-3.5">
								<label class="ct-field focus-within:border-primary">
									<span class="w-16 shrink-0 text-xs text-ui-ink-gray-500"
										>Dari</span
									>
									<input
										v-model="draft.dari"
										type="date"
										class="ct-field-input text-xs"
									/>
								</label>
								<label class="ct-field focus-within:border-primary">
									<span class="w-16 shrink-0 text-xs text-ui-ink-gray-500"
										>Sampai</span
									>
									<input
										v-model="draft.sampai"
										type="date"
										class="ct-field-input text-xs"
									/>
								</label>
							</div>

							<div class="mt-5 flex items-center gap-3">
								<button
									type="button"
									class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
									@click="resetTanggal"
								>
									Reset
								</button>
								<button
									type="button"
									class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
									@click="showTanggal = false"
								>
									Selesai
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { createResource } from 'frappe-ui'
import { statusBadge, rentang, angka, waktuUbah, tanggal } from '../data/cutiStatus'
import { useListPersistence } from '../composables/useListPersistence'

const listPersistence = useListPersistence('Cuti')

// Kolom yang masuk akal dipakai mengurutkan cuti. Daftar ini harus ada juga di
// SORT_FIELDS sisi server — di sana yang menolak kolom di luar daftar putih.
const SORT_FIELDS = [
	{ key: 'modified', label: 'Terakhir Diubah' },
	{ key: 'from_date', label: 'Tanggal Mulai' },
	{ key: 'to_date', label: 'Tanggal Selesai' },
	{ key: 'total_leave_days', label: 'Lama Cuti' },
	{ key: 'status', label: 'Status' },
	{ key: 'leave_type', label: 'Jenis Cuti' },
	{ key: 'employee_name', label: 'Nama Karyawan' },
	{ key: 'creation', label: 'Dibuat' },
]

const SARINGAN_KOSONG = {
	status: [],
	leave_type: [],
	cari: '',
	dari: '',
	sampai: '',
	perlu_aksi_saja: false,
}

const ringkasan = ref(null)
const opsiSaring = ref(null)
const items = ref([])

const showSort = ref(false)
const showFilter = ref(false)
const showStatus = ref(false)
const showJenis = ref(false)
const showTanggal = ref(false)
const sortField = ref('modified')
const sortDir = ref('desc')
const draftSortField = ref('modified')
const draftSortDir = ref('desc')

// `terpakai` yang dikirim ke server; `draft` yang sedang diubah di panel.
const terpakai = reactive({ ...SARINGAN_KOSONG })
const draft = reactive({ ...SARINGAN_KOSONG })

const jumlahSaringan = computed(() => {
	let n = 0
	if (terpakai.status.length) n++
	if (terpakai.leave_type.length) n++
	if (terpakai.cari.trim()) n++
	if (terpakai.dari || terpakai.sampai) n++
	if (terpakai.perlu_aksi_saja) n++
	return n
})

// Sub-sheet status & jenis cuti berbagi satu markup — isinya ditentukan mana
// yang sedang terbuka, supaya tidak ada dua blok hampir identik.
const pilihanSub = computed(() =>
	showStatus.value ? opsiSaring.value?.status || [] : opsiSaring.value?.leave_type || [],
)
const arraySub = computed(() => (showStatus.value ? draft.status : draft.leave_type))
function tutupSub() {
	showStatus.value = false
	showJenis.value = false
}
function resetTanggal() {
	draft.dari = ''
	draft.sampai = ''
}

// Warna titik disamakan dengan badge di kartu, jadi pilihan di panel dan hasil
// di daftar terbaca sebagai isyarat yang sama.
const TITIK = {
	Draft: 'bg-ui-surface-gray-400',
	'Menunggu Approval Atasan': 'bg-ui-surface-amber-400',
	'Menunggu Approval HR': 'bg-ui-surface-sky-400',
	'Menunggu Approval Direktur': 'bg-ui-surface-indigo-400',
	'Menunggu Persetujuan Karyawan': 'bg-blue-500',
	Approved: 'bg-green-500',
	Rejected: 'bg-red-500',
	Cancelled: 'bg-ui-surface-slate-400',
}
function titikStatus(s) {
	return TITIK[s] || 'bg-ui-surface-gray-300'
}

function ringkas(arr) {
	if (!arr.length) return ''
	return arr.length === 1 ? arr[0] : `${arr[0]} +${arr.length - 1}`
}
const ringkasStatus = computed(() => ringkas(draft.status))
const ringkasJenis = computed(() => ringkas(draft.leave_type))
const ringkasTanggal = computed(() => {
	if (draft.dari && draft.sampai) return `${tanggal(draft.dari)} – ${tanggal(draft.sampai)}`
	if (draft.dari) return `Sejak ${tanggal(draft.dari)}`
	if (draft.sampai) return `Sampai ${tanggal(draft.sampai)}`
	return ''
})

function pilihGanda(arr, nilai) {
	const i = arr.indexOf(nilai)
	if (i === -1) arr.push(nilai)
	else arr.splice(i, 1)
}

function openSort() {
	draftSortField.value = sortField.value
	draftSortDir.value = sortDir.value
	showSort.value = true
}
function applySort() {
	sortField.value = draftSortField.value
	sortDir.value = draftSortDir.value
	listPersistence.writePreferences({ sortField: sortField.value, sortDir: sortDir.value })
	showSort.value = false
	loadList()
}

function openFilter() {
	Object.assign(draft, {
		...terpakai,
		status: [...terpakai.status],
		leave_type: [...terpakai.leave_type],
	})
	showFilter.value = true
}
function applyFilter() {
	Object.assign(terpakai, {
		...draft,
		status: [...draft.status],
		leave_type: [...draft.leave_type],
	})
	listPersistence.writeSession({ filters: terpakai })
	showFilter.value = false
	loadList()
}
function clearFilter() {
	Object.assign(draft, { ...SARINGAN_KOSONG, status: [], leave_type: [] })
	Object.assign(terpakai, { ...SARINGAN_KOSONG, status: [], leave_type: [] })
	listPersistence.clearSession()
	showFilter.value = false
	loadList()
}
const loading = ref(true)
const loadError = ref('')

const pesanKosong = computed(() => {
	if (jumlahSaringan.value) return 'Tidak ada yang cocok dengan saringan.'
	if (ringkasan.value && !ringkasan.value.tertaut) return 'Tidak ada cuti untuk ditampilkan.'
	return 'Belum ada pengajuan cuti.'
})

const ringkasanRes = createResource({
	url: 'juragan.api.portal.cuti.get_ringkasan',
	method: 'GET',
	auto: false,
	onSuccess: (d) => {
		ringkasan.value = d
	},
})

const listRes = createResource({
	url: 'juragan.api.portal.cuti.get_pengajuan',
	method: 'GET',
	auto: false,
	makeParams: () => {
		const p = { sort_field: sortField.value, sort_dir: sortDir.value }
		if (terpakai.status.length) p.status = JSON.stringify(terpakai.status)
		if (terpakai.leave_type.length) p.leave_type = JSON.stringify(terpakai.leave_type)
		if (terpakai.cari.trim()) p.cari = terpakai.cari.trim()
		if (terpakai.dari) p.dari = terpakai.dari
		if (terpakai.sampai) p.sampai = terpakai.sampai
		if (terpakai.perlu_aksi_saja) p.perlu_aksi_saja = 1
		return p
	},
	onSuccess: (d) => {
		items.value = d || []
		loadError.value = ''
	},
	onError: (e) => {
		items.value = []
		loadError.value = e?.messages?.[0] || e?.message || 'Gagal memuat data cuti.'
	},
})

async function loadList() {
	loading.value = true
	try {
		await listRes.fetch()
	} finally {
		loading.value = false
	}
}

const saringRes = createResource({
	url: 'juragan.api.portal.cuti.get_opsi_saring',
	method: 'GET',
	auto: false,
	onSuccess: (d) => {
		opsiSaring.value = d
	},
})

async function loadAll() {
	await Promise.all([ringkasanRes.fetch(), saringRes.fetch()])
	const saved = listPersistence.readSession({ filters: SARINGAN_KOSONG }).filters
	const statusOptions = opsiSaring.value?.status || []
	const leaveTypeOptions = opsiSaring.value?.leave_type || []
	saved.status = saved.status.filter((value) => statusOptions.includes(value))
	saved.leave_type = saved.leave_type.filter((value) => leaveTypeOptions.includes(value))
	Object.assign(terpakai, saved)
	const prefs = listPersistence.readPreferences({ sortField: 'modified', sortDir: 'desc' })
	if (SORT_FIELDS.some((field) => field.key === prefs.sortField))
		sortField.value = prefs.sortField
	if (['asc', 'desc'].includes(prefs.sortDir)) sortDir.value = prefs.sortDir
	await loadList()
}

onMounted(loadAll)
</script>

<style>
/* Cermin dari .dp-field di Data Pengajuan — baris field pada bottom-sheet
   Filter: border melingkupi ikon + isian, abu-abu default, biru saat fokus.
   Sengaja diberi awalan sendiri agar halaman ini tidak bergantung pada style
   milik komponen lain yang kebetulan sudah termuat. */
.ct-field {
	@apply flex w-full items-center gap-3 rounded-2xl border border-ui-line-gray-300 px-4 py-3.5 transition;
}
.ct-field-input {
	@apply w-full border-0 bg-transparent p-0 text-ui-ink-gray-800 placeholder-ui-ink-gray-500 caret-primary outline-none focus:ring-0;
}
.ct-field-ic {
	@apply h-5 w-5 shrink-0 text-ui-ink-gray-500;
}
.ct-field-chev {
	@apply h-4 w-4 shrink-0 text-ui-ink-gray-500;
}
</style>
